import { MakeLogicType, actions, connect, events, kea, key, listeners, path, props, reducers } from 'kea'

import { teamLogic } from 'scenes/teamLogic'

import { sessionRecordingsLiveCountRetrieve } from 'products/replay/frontend/generated/api'

export interface LiveRecordingsCountLogicProps {
    pollIntervalMs?: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface liveRecordingsCountLogicValues {
    currentProjectId: number | string // teamLogic
    activeRecordings: number | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface liveRecordingsCountLogicActions {
    pauseStream: () => {
        value: true
    }
    pollCount: () => {
        value: true
    }
    resumeStream: () => {
        value: true
    }
    setActiveRecordings: (activeRecordings: number) => {
        activeRecordings: number
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface liveRecordingsCountLogicMeta {
    key: number
}

export type liveRecordingsCountLogicType = MakeLogicType<
    liveRecordingsCountLogicValues,
    liveRecordingsCountLogicActions,
    LiveRecordingsCountLogicProps,
    liveRecordingsCountLogicMeta
>

export const liveRecordingsCountLogic = kea<liveRecordingsCountLogicType>([
    path((key) => ['lib', 'components', 'LiveUserCount', 'liveRecordingsCountLogic', key]),
    key((props) => props.pollIntervalMs ?? 30000),
    props({ pollIntervalMs: 30000 } as LiveRecordingsCountLogicProps),
    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),
    actions(() => ({
        pollCount: true,
        setActiveRecordings: (activeRecordings: number) => ({ activeRecordings }),
        pauseStream: true,
        resumeStream: true,
    })),
    reducers({
        activeRecordings: [
            null as number | null,
            {
                setActiveRecordings: (_, { activeRecordings }) => activeRecordings,
            },
        ],
    }),
    listeners(({ actions, values, cache, props }) => ({
        pollCount: async () => {
            try {
                const response = await sessionRecordingsLiveCountRetrieve(String(values.currentProjectId))
                actions.setActiveRecordings(response.active_recordings)
            } catch (error) {
                console.error('Failed to poll live recordings count:', error)
            }
        },
        pauseStream: () => {
            cache.disposables.dispose('countInterval')
        },
        resumeStream: () => {
            actions.pollCount()
            cache.disposables.add(() => {
                const intervalId = setInterval(() => {
                    actions.pollCount()
                }, props.pollIntervalMs ?? 30000)
                return () => clearInterval(intervalId)
            }, 'countInterval')
        },
    })),
    events(({ actions }) => ({
        afterMount: () => {
            actions.resumeStream()
        },
    })),
])
